<?php require __DIR__.'/../config.php';$t=trim($_GET['t']??'');$num=trim($_GET['order']??'');if(!$t||!$num)json_response(['ok'=>false],422);$s=db()->prepare("SELECT o.id,o.order_number,o.status,o.total,o.updated_at,l.name location_name FROM orders o JOIN qr_codes q ON q.id=o.qr_id LEFT JOIN locations l ON l.id=o.location_id WHERE q.token=? AND o.order_number=? LIMIT 1");$s->execute([$t,$num]);$o=$s->fetch();if(!$o)json_response(['ok'=>false],404);$h=db()->prepare("SELECT from_status,to_status,created_at FROM order_status_history WHERE order_id=? ORDER BY id");$h->execute([$o['id']]);json_response(['ok'=>true,'order'=>$o,'history'=>$h->fetchAll()]);
